"""Rewrite async_update_entry(entry, options=X) into write_entry_config(hass, entry, X)."""

import ast
import sys
from pathlib import Path


def rewrite(path: Path, only_lines: set[int] | None) -> int:
    src = path.read_text()
    tree = ast.parse(src)
    lines = src.splitlines(keepends=True)
    offsets = [0]
    for line in lines:
        offsets.append(offsets[-1] + len(line))

    def pos(lineno, col):
        return offsets[lineno - 1] + col

    edits = []
    for node in ast.walk(tree):
        if not (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "async_update_entry"
        ):
            continue
        if only_lines is not None and node.lineno not in only_lines:
            continue
        if len(node.keywords) != 1 or node.keywords[0].arg != "options":
            continue
        entry_src = ast.get_source_segment(src, node.args[0])
        opts_src = ast.get_source_segment(src, node.keywords[0].value)
        edits.append(
            (
                pos(node.lineno, node.col_offset),
                pos(node.end_lineno, node.end_col_offset),
                f"write_entry_config(hass, {entry_src}, {opts_src})",
            )
        )

    for start, end, new in sorted(edits, reverse=True):
        src = src[:start] + new + src[end:]
    if edits:
        path.write_text(src)
    return len(edits)


if __name__ == "__main__":
    target = Path(sys.argv[1])
    lines = {int(x) for x in sys.argv[2:]} or None
    print(rewrite(target, lines), "rewritten in", target)
