    this._name = '';
    this._pin = '';
    this._condition = '';
    this._pinVisible = false;
    this._pinLength = DEFAULT_PIN_LENGTH;
    this._enabled = true;
    this._error = undefined;
    this._showDialog = true;
}

private _close(): void {
    this._showDialog = false;
}

